// 4. Clean / Distill — binary -> text, strip noise, sha256 fileHash.
// Binary lives in $binary (n8n-binary-and-data-official), never $json.
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const crypto = require('crypto');
const raw = buf.toString('utf-8');
const distilled = raw.replace(/Page\s*\d+/gi, '').replace(/\r/g, '').trim();
const meta = $input.first().json;
const fileHash = crypto.createHash('sha256').update(buf).digest('hex');
return [{ json: { distilled, fileId: meta.id, fileName: meta.name, fileHash } }];

// 6. Collect — aggregate chunk items, attach file meta, deterministic pointIds.
// pointId = 60-bit int from sha256(fileHash:chunkIndex) -> re-drop overwrites, zero new points.
const crypto = require('crypto');
const file = $('4. Clean / Distill').first().json;
const chunks = $input.all().map((it) => it.json);
const meta = chunks.map((c, i) => {
  const h = crypto.createHash('sha256').update(file.fileHash + ':' + i).digest('hex');
  return { pointId: parseInt(h.slice(0, 15), 16), text: c.text, chunkIndex: i, fileId: file.fileId, fileName: file.fileName, fileHash: file.fileHash };
});
const body = JSON.stringify({ model: 'jina-embeddings-v5-text-small', task: 'retrieval.passage', dimensions: 1024, input: meta.map((m) => m.text) });
return [{ json: { body, meta } }];

// 8. Build upsert — join Jina vectors with chunk meta by index, JSON-safe via stringify.
const vecs = $input.first().json.data;
const meta = $('6. Collect (batch + pointIds)').first().json.meta;
const points = meta.map((m, i) => ({
  id: m.pointId,
  vector: vecs[i].embedding,
  payload: { text: m.text, source: 'drive', fileId: m.fileId, fileName: m.fileName, section: 'chunk-' + m.chunkIndex, chunkIndex: m.chunkIndex, fileHash: m.fileHash, ingestedAt: new Date().toISOString() }
}));
return [{ json: { pointsBody: JSON.stringify({ points }) } }];

// 10. Error Log — structured failure record, visible in executions.
// Template: wire Slack/email here for prod. Error item carries the upstream message.
const e = $input.first().json;
const msg = (e && (e.error?.message || e.message)) || JSON.stringify(e).slice(0, 500);
return [{ json: { error: 'gtm-01-stage1-failure', message: msg, time: new Date().toISOString() } }];
